"""Run instrumented modules through real pytest, preserving package metadata.

Compatibility with pytest-gremlins 1.9.0: its lightweight runner bypasses
fixtures/parametrization, and its import hook drops __file__ and package paths.
This script replaces both generated runner scripts; mutation generation is
still performed entirely by pytest-gremlins.
"""

from __future__ import annotations

import json
import os
import sys
from importlib.abc import MetaPathFinder
from importlib.machinery import ModuleSpec, PathFinder, SourceFileLoader
from pathlib import Path
from types import ModuleType
from typing import Any


class InstrumentedLoader(SourceFileLoader):
    def __init__(self, name: str, path: str, source: str) -> None:
        super().__init__(name, path)
        self.source = source

    def exec_module(self, module: ModuleType) -> None:
        exec(compile(self.source, self.path, "exec"), module.__dict__)  # noqa: S102


class InstrumentedFinder(MetaPathFinder):
    def __init__(self, sources: dict[str, str]) -> None:
        self.sources = {name.removesuffix(".__init__"): code for name, code in sources.items()}

    def find_spec(
        self, fullname: str, path: Any = None, target: ModuleType | None = None
    ) -> ModuleSpec | None:
        if fullname not in self.sources:
            return None
        spec = PathFinder.find_spec(fullname, path)
        if spec is None or spec.origin is None:
            raise ImportError(f"Cannot locate instrumented module {fullname}")
        spec.loader = InstrumentedLoader(fullname, spec.origin, self.sources[fullname])
        return spec


def main() -> int:
    root = Path(os.environ.get("GREMLIN_ROOTDIR", Path.cwd()))
    sys.path[:0] = [str(root), str(root / "src")]
    sources = json.loads(Path(os.environ["PYTEST_GREMLINS_SOURCES_FILE"]).read_text())
    sys.meta_path.insert(0, InstrumentedFinder(sources))
    import pytest

    return pytest.main(["-x", "-q", "--tb=short", "-p", "no:gremlins", *sys.argv[1:]])


if __name__ == "__main__":
    raise SystemExit(main())

"""Tests for the newly exposed QueryEngine methods.

Covers ``ancestors_of``, ``reachable_from``, ``entrypoint_paths_to``,
``nodes_with_annotation``, and ``functions_that_raise`` — methods that
existed in ``GraphStore`` but had no public-facing analogue.
"""

from __future__ import annotations

from pathlib import Path

from trailmark.models.annotations import AnnotationKind
from trailmark.query.api import QueryEngine


class TestAncestorsOf:
    def test_direct_caller_is_ancestor(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def sink():\n    pass\n\ndef caller():\n    sink()\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        ancestors = engine.ancestors_of("sink")
        names = {a["name"] for a in ancestors}
        assert "caller" in names

    def test_transitive_ancestor_surfaces(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def sink():\n    pass\ndef middle():\n    sink()\ndef top():\n    middle()\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        names = {a["name"] for a in engine.ancestors_of("sink")}
        assert {"middle", "top"}.issubset(names)

    def test_unknown_node_returns_empty(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text("def only():\n    pass\n")
        engine = QueryEngine.from_directory(str(tmp_path))
        assert engine.ancestors_of("does_not_exist") == []

    def test_node_with_no_callers_has_no_call_ancestors(self, tmp_path: Path) -> None:
        """A function with no callers has no call ancestors."""
        (tmp_path / "app.py").write_text("def solo():\n    pass\n")
        engine = QueryEngine.from_directory(str(tmp_path))
        assert engine.ancestors_of("solo") == []


class TestReachableFrom:
    def test_direct_callee_is_reachable(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def a():\n    b()\n\ndef b():\n    pass\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        names = {n["name"] for n in engine.reachable_from("a")}
        assert "b" in names

    def test_transitive_reachability(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def a():\n    b()\ndef b():\n    c()\ndef c():\n    pass\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        names = {n["name"] for n in engine.reachable_from("a")}
        assert {"b", "c"}.issubset(names)


class TestEntrypointPathsTo:
    def test_path_from_entrypoint_to_sink(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def main():\n    validate()\n"
            "def validate():\n    sensitive()\n"
            "def sensitive():\n    pass\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        paths = engine.entrypoint_paths_to("sensitive")
        assert paths, "Expected at least one entrypoint->sink path"
        assert any(p[0] == "app:main" and p[-1] == "app:sensitive" for p in paths), paths

    def test_unreachable_sink_returns_empty(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def main():\n    pass\n\ndef orphan():\n    pass\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        assert engine.entrypoint_paths_to("orphan") == []


class TestNodesWithAnnotation:
    def test_manual_annotation_retrievable(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text("def risky():\n    pass\n")
        engine = QueryEngine.from_directory(str(tmp_path))
        engine.annotate(
            "risky",
            AnnotationKind.FINDING,
            "manually flagged",
            source="test",
        )
        finds = engine.nodes_with_annotation(AnnotationKind.FINDING)
        names = {n["name"] for n in finds}
        assert "risky" in names

    def test_empty_when_no_annotations(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text("def ok():\n    pass\n")
        engine = QueryEngine.from_directory(str(tmp_path))
        assert engine.nodes_with_annotation(AnnotationKind.FINDING) == []


class TestFunctionsThatRaise:
    def test_raises_detected_from_python_source(self, tmp_path: Path) -> None:
        """Python parser populates exception_types from `raise` statements."""
        (tmp_path / "app.py").write_text(
            "def bad():\n    raise ValueError('nope')\n\ndef good():\n    return 1\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        raisers = engine.functions_that_raise("ValueError")
        names = {n["name"] for n in raisers}
        assert "bad" in names
        assert "good" not in names

    def test_unknown_exception_returns_empty(self, tmp_path: Path) -> None:
        (tmp_path / "app.py").write_text(
            "def bad():\n    raise ValueError('nope')\n",
        )
        engine = QueryEngine.from_directory(str(tmp_path))
        assert engine.functions_that_raise("KeyError") == []

"""Tests for the Circom language parser."""

from __future__ import annotations

import os
import tempfile

from trailmark.models.edges import EdgeConfidence, EdgeKind
from trailmark.models.graph import CodeGraph
from trailmark.models.nodes import NodeKind
from trailmark.parsers.circom.parser import CircomParser

SAMPLE_CODE = """\
pragma circom 2.0.0;

include "circomlib/poseidon.circom";

/// A simple multiplier template.
template Multiplier(n) {
    signal input in1;
    signal input in2;
    signal output out;

    out <== in1 * in2;
}

/// Range check with branching logic.
template RangeCheck(bits) {
    signal input in;
    signal output out;

    component n2b = Num2Bits(bits);
    n2b.in <== in;

    var sum = 0;
    for (var i = 0; i < bits; i++) {
        sum += n2b.out[i];
    }

    if (sum > 0) {
        out <== 1;
    } else {
        out <== 0;
    }
}

function factorial(n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

function add(a, b) {
    return a + b;
}

component main {public [in1, in2]} = Multiplier(32);
"""


def _parse_sample() -> tuple[CircomParser, CodeGraph]:
    parser = CircomParser()
    with tempfile.NamedTemporaryFile(
        suffix=".circom",
        mode="w",
        delete=False,
    ) as f:
        f.write(SAMPLE_CODE)
        f.flush()
        graph = parser.parse_file(f.name)
    os.unlink(f.name)
    return parser, graph


class TestCircomParserNodes:
    def test_finds_module(self) -> None:
        _, graph = _parse_sample()
        modules = [n for n in graph.nodes.values() if n.kind == NodeKind.MODULE]
        assert len(modules) == 1

    def test_finds_templates(self) -> None:
        _, graph = _parse_sample()
        templates = [n for n in graph.nodes.values() if n.kind == NodeKind.TEMPLATE]
        names = {t.name for t in templates}
        assert "Multiplier" in names
        assert "RangeCheck" in names

    def test_finds_functions(self) -> None:
        _, graph = _parse_sample()
        funcs = [
            n for n in graph.nodes.values() if n.kind == NodeKind.FUNCTION and n.name != "main"
        ]
        names = {f.name for f in funcs}
        assert "factorial" in names
        assert "add" in names

    def test_finds_main_component(self) -> None:
        _, graph = _parse_sample()
        main = graph.nodes.get(next(nid for nid, n in graph.nodes.items() if n.name == "main"))
        assert main is not None
        assert main.kind == NodeKind.FUNCTION

    def test_template_docstring(self) -> None:
        _, graph = _parse_sample()
        mult = next(n for n in graph.nodes.values() if n.name == "Multiplier")
        assert mult.docstring is not None
        assert "simple multiplier" in mult.docstring

    def test_template_id_format(self) -> None:
        _, graph = _parse_sample()
        templates = [n for n in graph.nodes.values() if n.kind == NodeKind.TEMPLATE]
        for tmpl in templates:
            assert ":" in tmpl.id


class TestCircomParserParameters:
    def test_template_params(self) -> None:
        _, graph = _parse_sample()
        mult = next(n for n in graph.nodes.values() if n.name == "Multiplier")
        assert len(mult.parameters) == 1
        assert mult.parameters[0].name == "n"

    def test_function_params(self) -> None:
        _, graph = _parse_sample()
        add_fn = next(n for n in graph.nodes.values() if n.name == "add")
        assert len(add_fn.parameters) == 2
        names = {p.name for p in add_fn.parameters}
        assert "a" in names
        assert "b" in names

    def test_params_are_untyped(self) -> None:
        _, graph = _parse_sample()
        mult = next(n for n in graph.nodes.values() if n.name == "Multiplier")
        assert mult.parameters[0].type_ref is None

    def test_no_return_type(self) -> None:
        _, graph = _parse_sample()
        factorial = next(n for n in graph.nodes.values() if n.name == "factorial")
        assert factorial.return_type is None


class TestCircomParserComplexity:
    def test_simple_template_complexity(self) -> None:
        _, graph = _parse_sample()
        mult = next(n for n in graph.nodes.values() if n.name == "Multiplier")
        assert mult.cyclomatic_complexity == 1

    def test_branching_template_complexity(self) -> None:
        _, graph = _parse_sample()
        rc = next(n for n in graph.nodes.values() if n.name == "RangeCheck")
        assert rc.cyclomatic_complexity is not None
        assert rc.cyclomatic_complexity >= 3

    def test_branches_tracked(self) -> None:
        _, graph = _parse_sample()
        rc = next(n for n in graph.nodes.values() if n.name == "RangeCheck")
        assert len(rc.branches) > 0

    def test_function_complexity(self) -> None:
        _, graph = _parse_sample()
        factorial = next(n for n in graph.nodes.values() if n.name == "factorial")
        assert factorial.cyclomatic_complexity is not None
        assert factorial.cyclomatic_complexity >= 2

    def test_simple_function_complexity(self) -> None:
        _, graph = _parse_sample()
        add_fn = next(n for n in graph.nodes.values() if n.name == "add")
        assert add_fn.cyclomatic_complexity == 1


class TestCircomParserEdges:
    def test_contains_edges(self) -> None:
        _, graph = _parse_sample()
        contains = [e for e in graph.edges if e.kind == EdgeKind.CONTAINS]
        assert len(contains) > 0

    def test_call_edges_from_template(self) -> None:
        _, graph = _parse_sample()
        calls = [e for e in graph.edges if e.kind == EdgeKind.CALLS]
        rc_calls = [e for e in calls if "RangeCheck" in e.source_id]
        assert len(rc_calls) > 0

    def test_call_edges_from_function(self) -> None:
        _, graph = _parse_sample()
        calls = [e for e in graph.edges if e.kind == EdgeKind.CALLS]
        fact_calls = [e for e in calls if "factorial" in e.source_id]
        assert len(fact_calls) > 0

    def test_main_calls_template(self) -> None:
        _, graph = _parse_sample()
        calls = [e for e in graph.edges if e.kind == EdgeKind.CALLS]
        main_calls = [e for e in calls if "main" in e.source_id]
        assert len(main_calls) == 1
        assert "Multiplier" in main_calls[0].target_id

    def test_call_confidence(self) -> None:
        _, graph = _parse_sample()
        calls = [e for e in graph.edges if e.kind == EdgeKind.CALLS]
        assert all(e.confidence == EdgeConfidence.CERTAIN for e in calls)


class TestCircomParserDependencies:
    def test_imports_tracked(self) -> None:
        _, graph = _parse_sample()
        assert "poseidon" in graph.dependencies


class TestCircomParseDirectory:
    def test_parses_multiple_files(self) -> None:
        parser = CircomParser()
        code_a = "template A() { signal input x; }\n"
        code_b = "template B() { signal output y; }\n"
        with tempfile.TemporaryDirectory() as tmpdir:
            for name, code in [("a.circom", code_a), ("b.circom", code_b)]:
                path = os.path.join(tmpdir, name)
                with open(path, "w") as f:
                    f.write(code)
            graph = parser.parse_directory(tmpdir)
        assert graph.language == "circom"
        assert graph.root_path == tmpdir
        names = {n.name for n in graph.nodes.values()}
        assert "A" in names
        assert "B" in names

    def test_ignores_wrong_extensions(self) -> None:
        parser = CircomParser()
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "skip.txt")
            with open(path, "w") as f:
                f.write("not source code")
            graph = parser.parse_directory(tmpdir)
        assert len(graph.nodes) == 0

"""Tests for GraphStore edge cases."""

from __future__ import annotations

from trailmark.models import (
    CodeEdge,
    CodeGraph,
    CodeUnit,
    EdgeKind,
    NodeKind,
    SourceLocation,
)
from trailmark.storage.graph_store import GraphStore

_LOC = SourceLocation(file_path="test.py", start_line=1, end_line=10)


def _make_node(node_id: str, name: str) -> CodeUnit:
    return CodeUnit(
        id=node_id,
        name=name,
        kind=NodeKind.FUNCTION,
        location=_LOC,
    )


def _build_store() -> GraphStore:
    nodes = {
        "mod:a": _make_node("mod:a", "a"),
        "mod:b": _make_node("mod:b", "b"),
        "mod:Cls.method": _make_node("mod:Cls.method", "method"),
    }
    edges = [
        CodeEdge(
            source_id="mod:a",
            target_id="mod:b",
            kind=EdgeKind.CALLS,
        ),
    ]
    graph = CodeGraph(nodes=nodes, edges=edges)
    return GraphStore(graph)


class TestCalleesNonexistent:
    def test_callees_of_missing_node(self) -> None:
        store = _build_store()
        assert store.callees_of("nonexistent") == []


class TestPathsBetweenNonexistent:
    def test_paths_missing_src(self) -> None:
        store = _build_store()
        assert store.paths_between("zzz", "mod:b") == []

    def test_paths_missing_dst(self) -> None:
        store = _build_store()
        assert store.paths_between("mod:a", "zzz") == []


class TestReachableFromNonexistent:
    def test_reachable_missing_node(self) -> None:
        store = _build_store()
        assert store.reachable_from("zzz") == set()


class TestFindNodeMethod:
    def test_find_by_method_name(self) -> None:
        store = _build_store()
        node = store.find_node("method")
        assert node is not None
        assert node.id == "mod:Cls.method"

    def test_find_returns_none(self) -> None:
        store = _build_store()
        assert store.find_node("nonexistent") is None

